INSERT INTO prerequisites (course_id, prerequisite_id) SELECT c1.id, c2.id FROM courses c1 JOIN courses c2 ON c2.program_id = c1.program_id JOIN programs p ON p.id = c1.program_id WHERE p.program_code = 'BSCE' AND c1.course_code = 'MATH2' AND c2.course_code = 'MATH1';